/**
 * Cross-module regression for: "Recovery authorization must survive effect admission".
 *
 * Real production modules linked together:
 *   - execution/effect-gate.ts        (owner-facing gate + procedure-facing admission)
 *   - execution/tools.ts              (cleared-call executor)
 *   - session/values.ts, session/types.ts, session/commit.ts (durable address/commit layer)
 *   - runtime/progress.ts             (durable tool-output checkpoint channel)
 *   - runtime/drive/tool-placement.ts (batch source + outcome staging/placement)
 *   - runtime/drive/tools.ts          (recovery admission decision + effect publication)
 *
 * Boundary fakes (not part of the defect surface):
 *   - `@earendil-works/pi-ai` validateToolArguments
 *   - `../context.ts` withAbortSignal
 *   - `../../session/session.ts` SessionInvariantError
 *   - a minimal durable Lane/Drive pair backed by an in-memory value store
 *
 * Run with: node --experimental-vm-modules .prale-eval/regression.mjs
 */
import assert from "node:assert/strict";
import * as path from "node:path";
import { fileURLToPath } from "node:url";
import { createGraph } from "./subject.mjs";

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");

const HARNESS = "packages/agent/src/harness";
const MODULES = {
	effectGate: `${HARNESS}/execution/effect-gate.ts`,
	executionTools: `${HARNESS}/execution/tools.ts`,
	sessionTypes: `${HARNESS}/session/types.ts`,
	sessionValues: `${HARNESS}/session/values.ts`,
	sessionCommit: `${HARNESS}/session/commit.ts`,
	progress: `${HARNESS}/runtime/progress.ts`,
	placement: `${HARNESS}/runtime/drive/tool-placement.ts`,
	driveTools: `${HARNESS}/runtime/drive/tools.ts`,
};

const OPERATION_ID = "op-1";
const TURN_ID = "turn-1";
const ASSISTANT_ENTRY_ID = "assistant-1";
const RESULT_ENTRY_ID = "result-0";
const TOOL_CALL_ID = "call-0";

const ZERO_USAGE = {
	input: 0,
	output: 0,
	cacheRead: 0,
	cacheWrite: 0,
	totalTokens: 0,
	cost: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0, total: 0 },
};

const CONFIGURATION = {
	model: { provider: "fake", modelId: "fake-model" },
	thinkingLevel: "off",
	activeToolNames: ["effect"],
};

/** Convert a value created inside the VM realm into host plain data for strict comparison. */
const plain = (value) => (value === undefined ? undefined : JSON.parse(JSON.stringify(value)));
const textOf = (content) =>
	(content ?? []).flatMap((part) => (part.type === "text" ? [part.text] : [])).join("\n");

function deferred() {
	let resolve;
	const promise = new Promise((settle) => {
		resolve = settle;
	});
	return { promise, resolve };
}

/** In-memory durable store with an ordered observation log. */
function createStore(initial = []) {
	const values = new Map();
	const entries = new Map();
	const observations = [];
	let seq = 0;
	const addressKey = (address) => `${address.namespace}\u0000${address.key}`;
	const store = {
		observations,
		set(namespace, key, value) {
			values.set(`${namespace}\u0000${key}`, { namespace, key, value, seq: (seq += 1) });
		},
		get(namespace, key) {
			return values.get(`${namespace}\u0000${key}`)?.value;
		},
		entry(id) {
			return entries.get(id);
		},
		mark(label, detail) {
			observations.push({ at: observations.length, label, detail });
			return observations.length - 1;
		},
		apply(writes) {
			const firstSeq = seq + 1;
			for (const write of writes ?? []) {
				if (write.kind === "value") {
					const key = `${write.namespace}\u0000${write.key}`;
					if (write.op === "set") {
						values.set(key, { namespace: write.namespace, key: write.key, value: write.value, seq: (seq += 1) });
					} else {
						values.delete(key);
						seq += 1;
					}
					store.mark(write.op === "set" ? "value:set" : "value:delete", `${write.namespace}/${write.key}`);
					continue;
				}
				if (write.kind === "entry") {
					entries.set(write.entry.id, { ...write.entry, seq: (seq += 1) });
					store.mark("entry:insert", write.entry.id);
					continue;
				}
				if (write.kind === "list") {
					seq += 1;
					store.mark("list:write", `${write.namespace}/${write.key}`);
					continue;
				}
				seq += 1;
				store.mark("usage:insert", "usage");
			}
			return {
				firstSeq,
				seqs: (writes ?? []).map((_, index) => firstSeq + index),
				timestamp: observations.length,
				stats: { usage: { ...ZERO_USAGE } },
			};
		},
		reader: {
			async getValue(address) {
				const stored = values.get(addressKey(address));
				return stored === undefined ? undefined : { address, value: stored.value, seq: stored.seq };
			},
			async scanValues(prefix) {
				const stem = `${prefix.namespace}\u0000${prefix.key}`;
				const found = [];
				for (const [key, stored] of values) {
					if (!key.startsWith(stem)) continue;
					found.push({
						address: { namespace: stored.namespace, key: stored.key, kind: "value" },
						value: stored.value,
						seq: stored.seq,
					});
				}
				return found;
			},
			async getEntries(ids) {
				const found = new Map();
				for (const id of ids) if (entries.has(id)) found.set(id, entries.get(id));
				return found;
			},
			async readList() {
				return [];
			},
		},
	};
	for (const [namespace, key, value] of initial) store.set(namespace, key, value);
	return store;
}

const duplicateWrite = (namespace, key, value) => ({ kind: "value", op: "set", namespace, key, value });
const operationStateWrite = (namespace, key, value) => duplicateWrite(namespace, key, value);

/** Minimal durable Lane: one serialized state line plus a callback-driven schema. */
function createLane({ store, operation, config, onEvent }) {
	let state = {
		tipId: "assistant-1",
		configuration: CONFIGURATION,
		inbox: [],
		lastOperationId: null,
		operation: {
			meta: {
				operationId: OPERATION_ID,
				lane: "main",
				sourceTipId: null,
				startedAt: 1,
				intent: { kind: "run", promptEntryIds: [] },
			},
			state: operation,
		},
	};
	let tail = Promise.resolve();
	const locked = (run) => {
		const started = tail.then(run, run);
		tail = started.then(
			() => undefined,
			() => undefined,
		);
		return started;
	};
	const applyCommit = (decision) => {
		const commit = store.apply(decision.writes);
		if (decision.next !== undefined) state = decision.next;
		if (decision.operationState !== undefined) {
			state = { ...state, operation: { meta: state.operation.meta, state: decision.operationState } };
		}
		if (decision.lane !== undefined) state = { ...state, ...decision.lane };
		const value = decision.materialize === undefined ? undefined : decision.materialize(commit);
		const events = decision.events === undefined ? [] : decision.events(commit);
		if (events.length > 0) void lane.emitBatch(events);
		return value;
	};
	const settle = (plan) =>
		locked(async () => {
			const operation0 = state.operation;
			const decision = await plan(state, operation0.state, operation0.meta, store.reader);
			if (decision.kind !== "commit") return decision.kind === "return" ? decision.result : undefined;
			return applyCommit({
				writes: [
					...decision.writes,
					operationStateWrite("pi.op.state", OPERATION_ID, decision.operationState),
				],
				next: {
					...state,
					...(decision.lane ?? {}),
					operation: { meta: operation0.meta, state: decision.operationState },
				},
				materialize: decision.materialize,
				...(decision.events === undefined ? {} : { events: decision.events }),
			});
		});
	const lane = {
		name: "main",
		session: { idGenerator: { next: () => `generated-${(sequence += 1)}` } },
		get state() {
			return state;
		},
		readConfig: () => config,
		hooks: { runToolWithGate: async () => undefined },
		emitBatch: async (events) => {
			if (onEvent !== undefined) await onEvent(events, store);
		},
		command: (plan) =>
			locked(async () => {
				const decision = await plan(state, store.reader);
				if (decision.kind === "return") return decision.result;
				if (decision.kind === "reject") throw decision.error;
				return applyCommit(decision);
			}),
		settleOperation: (_capability, plan) => settle(plan),
		continueOperation: (capability, plan) =>
			settle(async (current, latest, meta, reader) => {
				if (latest.control.status === "cancel_requested") {
					return { kind: "return", result: { kind: "cancel_requested" } };
				}
				const decision = await plan(current, latest, meta, reader);
				if (decision.kind === "return") {
					return { kind: "return", result: { kind: "result", value: decision.result } };
				}
				return {
					...decision,
					materialize: (commit) => ({ kind: "result", value: decision.materialize(commit) }),
				};
			}),
	};
	let sequence = 0;
	return lane;
}

function createDrive(createGate) {
	const { gate, control } = createGate();
	return {
		operationId: OPERATION_ID,
		context: {},
		gate,
		closeSignal: new AbortController().signal,
		beginAbort: (cancellation) => control.beginAbort(cancellation),
		signalAbort: () => control.signalAbort(),
		closeGate: (error) => control.close(error),
	};
}

function assistantMessageWith(toolName, args) {
	return {
		entry: {
			id: ASSISTANT_ENTRY_ID,
			parentId: null,
			type: "message",
			seq: 1,
			timestamp: 1,
			message: {
				role: "assistant",
				content: [{ type: "toolCall", id: TOOL_CALL_ID, name: toolName, arguments: args }],
				stopReason: "toolUse",
				timestamp: 1,
			},
		},
	};
}

function toolsOperation(call, { turnId = TURN_ID, toolExecution = "sequential" } = {}) {
	return {
		at: "tools",
		control: { status: "running" },
		settings: { compaction: {}, steeringMode: "queue", followUpMode: "queue", toolExecution },
		latestAssistantEntryId: ASSISTANT_ENTRY_ID,
		batch: {
			assistantEntryId: ASSISTANT_ENTRY_ID,
			configuration: CONFIGURATION,
			turnId,
			calls: [call],
		},
	};
}

const effectPendingCall = (replay) => ({
	status: "effect_pending",
	sourceIndex: 0,
	resultEntryId: RESULT_ENTRY_ID,
	replay,
});

function createTool({ name = "effect", replay, execute }) {
	return {
		name,
		label: name,
		description: name,
		parameters: { type: "object" },
		...(replay === undefined ? {} : { replay }),
		execute,
	};
}

async function loadHarness() {
	const bindings = {
		validateToolArguments: (tool, call) => {
			if (call.arguments === null || typeof call.arguments !== "object") {
				throw new Error(`Validation failed for tool "${tool.name}"`);
			}
			return { ...call.arguments };
		},
		withAbortSignal: (signal, context) => ({ ...context, abortSignal: signal }),
		SessionInvariantError: class SessionInvariantError extends Error {
			constructor(message) {
				super(message);
				this.name = "SessionInvariantError";
			}
		},
	};
	const graph = createGraph(ROOT, MODULES, bindings, {}, {});
	const [effectGate, executionTools, values, driveTools] = await Promise.all([
		graph.module("effectGate"),
		graph.module("executionTools"),
		graph.module("sessionValues"),
		graph.module("driveTools"),
	]);
	return { effectGate, executionTools, values, driveTools };
}

/**
 * Recovery fixture: one interrupted effect whose durable argument checkpoint
 * ("persisted") differs from the stale model arguments ("from-model").
 */
async function runRecovery({
	modules,
	toolReplay = "safe",
	callReplay = "safe",
	includeTool = true,
	cancel = false,
	closeError,
	execute,
	onEvent,
}) {
	const { values } = modules;
	const store = createStore([
		["pi.pending.tool_output", `${OPERATION_ID}:${RESULT_ENTRY_ID}`, {
			content: [{ type: "text", text: "durable partial" }],
			details: { progress: "kept" },
		}],
		[values.operationToolArgs(OPERATION_ID, TURN_ID, 0).namespace, values.operationToolArgs(OPERATION_ID, TURN_ID, 0).key, { value: "persisted" }],
	]);
	const assistant = assistantMessageWith("effect", { value: "from-model" });
	store.entry; // entries are inserted through commit writes
	store.apply([{ kind: "entry", entry: assistant.entry }]);
	store.mark("fixture:ready");

	const observed = [];
	const tool = includeTool
		? createTool({
				replay: toolReplay,
				execute: async (_id, args, onUpdate) => {
					observed.push({ args: plain(args) });
					store.mark("tool:execute:start", JSON.stringify(args));
					const checkpointBefore = store.get(
						"pi.pending.tool_output",
						`${OPERATION_ID}:${RESULT_ENTRY_ID}`,
					);
					observed.push({ checkpointBeforeCall: plain(checkpointBefore) });
					if (execute !== undefined) await execute({ args, onUpdate, store });
					store.mark("tool:execute:end");
					return { content: [{ type: "text", text: `effect:${args.value}` }], details: { value: args.value } };
				},
			})
		: undefined;

	const lane = createLane({
		store,
		operation: toolsOperation(effectPendingCall(callReplay)),
		config: {
			tools: tool === undefined ? [] : [tool],
			toolContext: undefined,
			resources: {},
			streamOptions: {},
			retryPolicy: {},
			compaction: {},
			steeringMode: "queue",
			followUpMode: "queue",
			toolExecution: "sequential",
			systemPrompt: undefined,
			toProviderMessages: (messages) => messages,
			entryProjectors: {},
		},
		onEvent,
	});
	const drive = createDrive(modules.effectGate.createGate);
	if (cancel) drive.beginAbort(Promise.resolve());
	if (closeError !== undefined) drive.closeGate(closeError);
	const result = await modules.driveTools.runTools(lane, drive, lane.state.operation.state);
	return { store, observed, result, lane, drive };
}

const events = (store) => store.observations;

function observationIndex(store, label, detail) {
	const index = store.observations.findIndex(
		(entry) => entry.label === label && (detail === undefined || entry.detail === detail),
	);
	assert.notEqual(index, -1, `expected observation ${label}${detail === undefined ? "" : ` ${detail}`}`);
	return index;
}

describe("effect gate admission", async () => {
	const modules = await loadHarness();
	it("refuses admission once cancellation is requested", () => {
		const { gate, control } = modules.effectGate.createGate();
		const cancellation = Promise.resolve();
		control.beginAbort(cancellation);
		let invoked = 0;
		assert.throws(
			() =>
				gate.admit(() => {
					invoked += 1;
					return "executed";
				}),
			(error) => {
				assert.ok(error instanceof modules.effectGate.AbortRequested);
				assert.equal(error.cancellation, cancellation);
				return true;
			},
		);
		assert.equal(invoked, 0);
		assert.equal(gate.signal.aborted, false, "the gate signal follows the durable cancellation, not admission");
	});

	it("refuses admission once the gate is closed and still admits open work", () => {
		const open = modules.effectGate.createGate();
		assert.equal(
			open.gate.admit(() => "executed"),
			"executed",
		);
		const closed = modules.effectGate.createGate();
		const failure = new Error("harness closed");
		closed.control.close(failure);
		assert.throws(() => closed.gate.admit(() => "executed"), (error) => error === failure);
		assert.equal(closed.gate.signal.aborted, true);
	});
});

describe("cleared-call execution", async () => {
	const modules = await loadHarness();
	it("executes the cleared arguments instead of the original model arguments", async () => {
		const providerCall = {
			type: "toolCall",
			id: TOOL_CALL_ID,
			name: "effect",
			arguments: { value: "from-model" },
		};
		const seen = [];
		const tool = createTool({
			execute: async (_id, args) => {
				seen.push(plain(args));
				return { content: [{ type: "text", text: "done" }], details: {} };
			},
		});
		const prepared = modules.executionTools.prepareToolCall(providerCall, [tool]);
		assert.equal(prepared.kind, undefined, "expected a prepared call");
		const cleared = modules.executionTools.applyBeforeToolDecision(prepared, { args: { value: "cleared" } });
		assert.equal(cleared.kind, undefined, "expected a cleared call");
		assert.deepEqual(plain(cleared.args), { value: "cleared" });

		const { gate } = modules.effectGate.createGate();
		const executed = await modules.executionTools.executeToolCall(
			cleared,
			gate,
			() => {},
			undefined,
			{ invocationId: RESULT_ENTRY_ID, operationId: OPERATION_ID, turnId: TURN_ID, getMemo: async () => undefined, setMemo: async () => {} },
			{},
		);
		assert.deepEqual(seen, [{ value: "cleared" }]);
		assert.equal(executed.isError, false);
	});

	it("does not invoke the effect when the gate refuses admission", async () => {
		const seen = [];
		const cleared = {
			toolCall: { type: "toolCall", id: TOOL_CALL_ID, name: "effect", arguments: { value: "from-model" } },
			tool: createTool({
				execute: async () => {
					seen.push("executed");
					return { content: [], details: {} };
				},
			}),
			args: { value: "cleared" },
		};
		const { gate, control } = modules.effectGate.createGate();
		control.beginAbort(Promise.resolve());
		assert.throws(() =>
			modules.executionTools.executeToolCall(
				cleared,
				gate,
				() => {},
				undefined,
				{ invocationId: RESULT_ENTRY_ID, operationId: OPERATION_ID, turnId: TURN_ID, getMemo: async () => undefined, setMemo: async () => {} },
				{},
			),
		);
		assert.deepEqual(seen, []);
	});
});

describe("recovery admission", async () => {
	const modules = await loadHarness();

	it("replays a doubly declared safe effect with the persisted arguments", async () => {
		const finishEffect = deferred();
		const updateSeen = deferred();
		const updateDelivery = deferred();
		let sawPendingOutcome = undefined;
		const fixture = await runRecovery({
			modules,
			execute: async ({ onUpdate }) => {
				onUpdate?.({ content: [{ type: "text", text: "partial" }], details: { progress: "partial" } }, { checkpoint: true });
				await finishEffect.promise;
			},
			onEvent: async (batch) => {
				if (!batch.some((event) => event.type === "tool_update")) return;
				sawPendingOutcome ??= fixtureProbe();
				updateSeen.resolve();
				await updateDelivery.promise;
			},
		});
		const fixtureProbe = () => "probe";
		assert.equal(sawPendingOutcome, undefined);
		await updateSeen.promise;
		// The effect is still in flight: the durable progress checkpoint exists, no outcome is published yet.
		assert.notEqual(
			fixture.store.get("pi.pending.tool_output", `${OPERATION_ID}:${RESULT_ENTRY_ID}`),
			undefined,
		);
		assert.equal(fixture.store.get("pi.pending.entry", RESULT_ENTRY_ID), undefined);
		assert.equal(fixture.store.entry(RESULT_ENTRY_ID), undefined);
		finishEffect.resolve();
		updateDelivery.resolve();
		const result = await fixtureRun(fixture);
		assert.deepEqual(plain(result), { kind: "continue" });

		// The executor received the persisted arguments, never the stale model arguments.
		assert.deepEqual(fixture.observed[0], { args: { value: "persisted" } });
		// The old checkpoint was cleared before the effect was invoked.
		assert.equal(fixture.observed[1], { checkpointBeforeCall: undefined });

		const deleteCheckpoint = observationIndex(fixture.store, "value:delete", `pi.pending.tool_output/${OPERATION_ID}:${RESULT_ENTRY_ID}`);
		const executeStart = observationIndex(fixture.store, "tool:execute:start");
		const executeEnd = observationIndex(fixture.store, "tool:execute:end");
		const progressWrite = observationIndex(fixture.store, "value:set", `pi.pending.tool_output/${OPERATION_ID}:${RESULT_ENTRY_ID}`);
